package io.tornado.reporting;import io.tornado.persistence.Direction;import java.util.*;public final class MixConsensus{private MixConsensus(){}public static Result decide(int totalMethods,Collection<Direction>signals){int up=0,down=0;for(Direction d:signals){if(d==Direction.UP)up++;else if(d==Direction.DOWN)down++;}int required=totalMethods/2+1;if(Math.max(up,down)<required)return new Result(null,Math.max(up,down),required);return new Result(up>down?Direction.UP:Direction.DOWN,Math.max(up,down),required);}public record Result(Direction direction,int agreement,int required){public boolean decisive(){return direction!=null;}}}
